sys_script.script:
(function executeRule(current, previous /*null when async*/) {

	// Add your code here
	    var gr = new GlideRecord('x_2140056_lab_eq_0_booking');
    gr.addQuery('equipment', current.equipment);
    gr.addQuery('status', 'Approved');
    gr.query();

    if (gr.next()) {
        gs.addErrorMessage("This equipment is already booked.");
        current.setAbortAction(true);
    }

})(current, previous);
